    const rows=p.days.map(d=>['D'+d.day,esc(d.date),fmt(d.planOutput,0),'<b>'+fmt(d.pieces,0)+'</b>',(d.pieces-d.planOutput>=0?'+':'')+fmt(d.pieces-d.planOutput,0),fmt(d.planManpower,0),fmt(d.workers,0),pct(d.planEff),d.eff==null?'—':(d.eff<d.planEff*0.85?'<span style="color:var(--red)"><b>'+pct(d.eff)+'</b></span>':'<b>'+pct(d.eff)+'</b>'),fmt(d.approvedSmv,3),fmt(d.appliedSmv,3)]);
